import json
import boto3
import os
import urllib.request
from graphql import graphql_sync, build_schema

# GraphQL schema for user management service
schema_str = """
type Query {
    user(filter: String!): User
    users(search: String): [User]
}

type User {
    id: ID!
    name: String!
    email: String!
    role: String!
}
"""

schema = build_schema(schema_str)

def get_aws_credentials():
    """Fetch temporary credentials from instance metadata for DynamoDB access"""
    metadata_url = "http://169.254.169.254/latest/meta-data/iam/security-credentials/"
    try:
        role_req = urllib.request.urlopen(metadata_url, timeout=2)
        role_name = role_req.read().decode()
        creds_url = f"{metadata_url}{role_name}"
        creds_req = urllib.request.urlopen(creds_url, timeout=2)
        return json.loads(creds_req.read().decode())
    except Exception as e:
        return None

def resolve_user(root, info, filter):
    """Resolve user query - filter is passed directly to DynamoDB FilterExpression"""
    creds = get_aws_credentials()
    dynamodb = boto3.resource('dynamodb',
        region_name=os.environ.get('AWS_REGION', 'us-east-1'),
        aws_access_key_id=creds['AccessKeyId'] if creds else None,
        aws_secret_access_key=creds['SecretAccessKey'] if creds else None,
        aws_session_token=creds['Token'] if creds else None
    )
    table = dynamodb.Table(os.environ.get('USERS_TABLE', 'users'))

    # VULNERABLE: filter string is interpolated directly into FilterExpression
    # allowing injection of arbitrary DynamoDB filter conditions
    response = table.scan(
        FilterExpression=filter,
        ExpressionAttributeValues={':val': filter}
    )
    items = response.get('Items', [])
    if items:
        return items[0]
    return None

def resolve_users(root, info, search=None):
    """Resolve users list query"""
    dynamodb = boto3.resource('dynamodb', region_name=os.environ.get('AWS_REGION', 'us-east-1'))
    table = dynamodb.Table(os.environ.get('USERS_TABLE', 'users'))

    if search:
        # Also vulnerable - raw search term in expression
        response = table.scan(
            FilterExpression=f"contains(#n, :s) OR contains(email, :s) OR {search}",
            ExpressionAttributeNames={'#n': 'name'},
            ExpressionAttributeValues={':s': search}
        )
    else:
        response = table.scan()
    return response.get('Items', [])

query_type = schema.query_type
query_type.fields['user'].resolve = resolve_user
query_type.fields['users'].resolve = resolve_users

def lambda_handler(event, context):
    """AWS Lambda handler for GraphQL API"""
    try:
        body = json.loads(event.get('body', '{}'))
    except json.JSONDecodeError:
        return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid JSON'})}

    query = body.get('query', '')
    variables = body.get('variables', {})

    # Execute GraphQL query
    result = graphql_sync(schema, query, variable_values=variables)

    response_body = {}
    if result.data:
        response_body['data'] = result.data
    if result.errors:
        response_body['errors'] = [{'message': str(e)} for e in result.errors]

    return {
        'statusCode': 200,
        'headers': {'Content-Type': 'application/json'},
        'body': json.dumps(response_body, default=str)
    }
